        self.v = v; self.nxt = nxt; self.rnd = rnd

def solve(values):
    n = len(values)
    if n == 0: return []
    nodes = [N(values[i][0]) for i in range(n)]
    for i in range(n - 1):
        nodes[i].nxt = nodes[i + 1]
    mapping = {old: new for old, new in zip(_build_orig(values), nodes)}
    for i, (v, r) in enumerate(values):
        nodes[i].rnd = mapping.get(_orig_from_idx(i, r)) if r >= 0 else None
    return nodes

